/**
 * Post-deployment address sync script
 * Run after `npm run deploy:testnet` to automatically propagate
 * contract addresses to:
 *   - contracts/deployments.json  (already done by deploy.js)
 *   - backend/.env                (upserts ALTANA_SESSION_MANAGER, etc.)
 *   - frontend/src/contracts/addresses.js (auto-generated ES module)
 */

const fs = require("fs");
const path = require("path");

const ROOT = path.join(__dirname, "../..");
const DEPLOYMENTS_PATH = path.join(__dirname, "../deployments.json");
const BACKEND_ENV_PATH = path.join(ROOT, "backend/.env");
const FRONTEND_ADDRESSES_PATH = path.join(ROOT, "frontend/src/contracts/addresses.js");

function main() {
  if (!fs.existsSync(DEPLOYMENTS_PATH)) {
    console.error("❌  deployments.json not found. Run deploy:testnet first.");
    process.exit(1);
  }

  const deployments = JSON.parse(fs.readFileSync(DEPLOYMENTS_PATH, "utf8"));
  const { contracts, external, chainId, timestamp } = deployments;

  console.log("================================================");
  console.log("  ONCHAIN BAZAAR — POST-DEPLOY ADDRESS SYNC    ");
  console.log("================================================");
  console.log(`Network: ${deployments.network} (Chain ID: ${chainId})`);
  console.log(`Deployed at: ${timestamp}\n`);

  // ─── 1. Update backend/.env ───────────────────────────────────────────
  const envVarsToSync = {
    ALTANA_SESSION_MANAGER: contracts.AltanaSessionManager,
    SYRUP_SENTINEL: contracts.SyrupSentinelAgent,
    VENUS_GUARDIAN: contracts.VenusGuardianAgent,
    YIELD_MAX: contracts.YieldMaxAgent,
    CHAIN_WATCH: contracts.ChainWatchAgent,
  };

  let backendEnvContent = "";

  if (fs.existsSync(BACKEND_ENV_PATH)) {
    backendEnvContent = fs.readFileSync(BACKEND_ENV_PATH, "utf8");
  } else {
    // Bootstrap from example if .env doesn't exist yet
    const examplePath = path.join(ROOT, "backend/.env.example");
    if (fs.existsSync(examplePath)) {
      backendEnvContent = fs.readFileSync(examplePath, "utf8");
    }
  }

  // Upsert each env var
  for (const [key, value] of Object.entries(envVarsToSync)) {
    const regex = new RegExp(`^${key}=.*$`, "m");
    const newLine = `${key}=${value}`;

    if (regex.test(backendEnvContent)) {
      backendEnvContent = backendEnvContent.replace(regex, newLine);
    } else {
      backendEnvContent += `\n${newLine}`;
    }

    console.log(`  Backend .env → ${key}=${value}`);
  }

  fs.writeFileSync(BACKEND_ENV_PATH, backendEnvContent);
  console.log(`\n✅  backend/.env updated`);

  // ─── 2. Generate frontend/src/contracts/addresses.js ─────────────────
  const frontendAddressesDir = path.dirname(FRONTEND_ADDRESSES_PATH);
  if (!fs.existsSync(frontendAddressesDir)) {
    fs.mkdirSync(frontendAddressesDir, { recursive: true });
  }

  const addressesModule = `/**
 * AUTO-GENERATED by scripts/sync-addresses.js
 * DO NOT EDIT MANUALLY.
 * Last deployed: ${timestamp} on ${deployments.network} (Chain ID: ${chainId})
 */

export const DEPLOYED_ADDRESSES = ${JSON.stringify(
    {
      AltanaSessionManager: contracts.AltanaSessionManager,
      SyrupSentinelAgent: contracts.SyrupSentinelAgent,
      VenusGuardianAgent: contracts.VenusGuardianAgent,
      YieldMaxAgent: contracts.YieldMaxAgent,
      ChainWatchAgent: contracts.ChainWatchAgent,
      PancakeV3Router: external.PancakeV3Router,
      PancakeV2Router: external.PancakeV2Router,
    },
    null,
    2
  )};

export const DEPLOYMENT_META = {
  network: "${deployments.network}",
  chainId: ${chainId},
  deployedAt: "${timestamp}",
};
`;

  fs.writeFileSync(FRONTEND_ADDRESSES_PATH, addressesModule);
  console.log(`✅  frontend/src/contracts/addresses.js generated`);

  console.log("\n🎯  All addresses synced. Ready for testnet testing!");
  console.log("    Next: cd backend && python -m uvicorn main:app --reload --port 8000");
  console.log("    Next: cd frontend && npm run dev");
}

main();
